    Bug 2008645 - Fix browser_policy_passwordmanager.js when run by itself. r=aleca

    I think the key here is calling `setTimeout` on the content window instead of the main window.
    The rest is just tidying up.

    Differential Revision: https://phabricator.services.mozilla.com/D277945

diff --git a/mail/components/enterprisepolicies/tests/browser/browser_policy_passwordmanager.js b/mail/components/enterprisepolicies/tests/browser/browser_policy_passwordmanager.js
index d14f17b201d..8693a57ab1a 100644
--- a/mail/components/enterprisepolicies/tests/browser/browser_policy_passwordmanager.js
+++ b/mail/components/enterprisepolicies/tests/browser/browser_policy_passwordmanager.js
@@ -10,15 +10,10 @@ add_task(async function test_pwmanagerbutton() {
     },
   });

-  window.openPreferencesTab("panePrivacy");
-  await BrowserTestUtils.browserLoaded(window.preferencesTabType.tab.browser);
-  await new Promise(resolve => setTimeout(resolve));
-
-  is(
-    window.preferencesTabType.tab.browser.contentDocument.getElementById(
-      "showPasswords"
-    ).disabled,
-    true,
+  const prefWin = await window.openPreferencesTab("panePrivacy");
+  await new Promise(resolve => prefWin.setTimeout(resolve));
+  Assert.ok(
+    prefWin.document.getElementById("showPasswords").disabled,
     "showPasswords should be disabled."
   );
